/**
 * Unit pages, travel route pages, English versions and new articles.
 * Every field is set only if it is still empty, so anything already edited
 * in the Studio stays as it is. Content lives in data/2026-09-29-growth.json
 * (generated by scripts/content/apply.py).
 */
import { readFile } from 'node:fs/promises';

export default async function run(client) {
  const data = JSON.parse(await readFile(new URL('./data/2026-09-29-growth.json', import.meta.url), 'utf8'));
  const tx = client.transaction();

  for (const [id, fields] of Object.entries(data.cars)) tx.patch(id, (p) => p.setIfMissing(fields));
  for (const [id, en] of Object.entries(data.cities)) tx.patch(id, (p) => p.setIfMissing({ en }));
  for (const [id, en] of Object.entries(data.services)) tx.patch(id, (p) => p.setIfMissing({ en }));
  tx.patch('siteSettings', (p) => p.setIfMissing({ en: data.settings }));
  tx.patch('homePage', (p) => p.setIfMissing({ en: data.home }));

  // Route copy goes onto the existing route rows, matched by origin + destination.
  const travel = await client.fetch(`*[_type == "servicePage" && template == "travel"][0]{_id, routes[]{_key, origin, dest}}`);
  if (travel) {
    for (const r of data.routes) {
      const row = travel.routes?.find((x) => x.origin === r.origin && x.dest === r.dest);
      if (!row) { console.warn(`route ${r.origin} → ${r.dest} not found, skipped`); continue; }
      const { origin, dest, ...fields } = r;
      const base = `routes[_key=="${row._key}"]`;
      tx.patch(travel._id, (p) => p.setIfMissing(Object.fromEntries(Object.entries(fields).map(([k, v]) => [`${base}.${k}`, v]))));
    }
  }

  for (const post of data.posts) tx.createIfNotExists(post);

  const res = await tx.commit({ visibility: 'sync' });
  console.log(`growth: ${res.results.length} mutations applied (${data.posts.length} posts, ${Object.keys(data.cars).length} cars, ${data.routes.length} routes).`);
}
